struct MemoListView: View {
    @State private var hidesCompleted = false
    let memos: [Memo]

    var visibleMemos: [Memo] {
        hidesCompleted ? memos.filter { !$0.isCompleted } : memos
    }

    var body: some View {
        Toggle("완료 숨기기", isOn: $hidesCompleted)
        Text("할 일 \(visibleMemos.count)개")
    }
}
